from qiskit import QuantumCircuit
from qiskit.circuit import Gate

def count_gates(circuit: QuantumCircuit) -> int:
    """Return the total number of unitary gates in the circuit."""
    return sum(1 for instruction, _, _ in circuit.data if isinstance(instruction, Gate))

from qiskit import QuantumCircuit
import qiskit.qasm2

def convert_quantum_circuit_to_qasm_string(circuit: QuantumCircuit) -> str:
    """Given a QuantumCircuit, convert it into a QASM 2.0 string and return it."""
    return qiskit.qasm2.dumps(circuit)

from qiskit.quantum_info import ScalarOp

def compose_scalar_ops() -> ScalarOp:
    """Create two ScalarOp objects with dimension 2 and coefficient 2, compose them together, and return the resulting ScalarOp."""
    op1 = ScalarOp(2, coeff=2)
    op2 = ScalarOp(2, coeff=2)
    return op1.compose(op2)
